-- ============================================================================
--  SAMOT Launcher — Migration v27: featured_slides — 2 правки
--  1) FIX «cannot insert a non-DEFAULT value into column "id"»:
--     столбцу id возвращаем generated BY DEFAULT (можно опускать id в INSERT,
--     старый upsert_featured всегда передавал id явно → ошибка при создании).
--  2) body TEXT: текст для окна «Подробнее» (фестиваль/событие без ссылки).
--     Кнопка открывает это окно, если cta_url пуст, а body заполнен.
--     Если и cta_url, и body пусты — постер без кнопки («постер говорит сам за себя»).
--  Применить в SQL Editor текущего Supabase проекта.
-- ============================================================================

alter table public.featured_slides alter column id set generated by default;
alter table public.featured_slides add column if not exists body text not null default '';

-- пересоздаём upsert_featured: id можно не передавать
drop function if exists public.upsert_featured(bigint, text, text, text, text, text, int, boolean, timestamptz);

create or replace function public.upsert_featured(
  p_id bigint,
  p_title text,
  p_tagline text,
  p_image_url text,
  p_cta_label text,
  p_cta_url text,
  p_sort int,
  p_published boolean,
  p_expires_at timestamptz,
  p_body text default ''
) returns bigint language plpgsql security definer set search_path = public as
$$
declare v_id bigint;
begin
  if not public.is_super() then raise exception 'Only super admin'; end if;

  if p_id is null then
    insert into public.featured_slides
      (title, tagline, image_url, cta_label, cta_url, body, sort, published, expires_at, created_by)
    values
      (p_title, coalesce(p_tagline, ''), coalesce(p_image_url, ''), coalesce(p_cta_label, ''),
       coalesce(p_cta_url, ''), coalesce(p_body, ''), coalesce(p_sort, 0),
       coalesce(p_published, true), p_expires_at, auth.uid())
    returning id into v_id;
  else
    insert into public.featured_slides
      (id, title, tagline, image_url, cta_label, cta_url, body, sort, published, expires_at, created_by)
    values
      (p_id, p_title, coalesce(p_tagline, ''), coalesce(p_image_url, ''), coalesce(p_cta_label, ''),
       coalesce(p_cta_url, ''), coalesce(p_body, ''), coalesce(p_sort, 0),
       coalesce(p_published, true), p_expires_at, auth.uid())
    on conflict (id) do update set
      title = excluded.title, tagline = excluded.tagline, image_url = excluded.image_url,
      cta_label = excluded.cta_label, cta_url = excluded.cta_url, body = excluded.body,
      sort = excluded.sort, published = excluded.published, expires_at = excluded.expires_at
    returning id into v_id;
  end if;

  perform public.audit_log('featured_upsert', 'featured_slides', v_id::text, null,
    jsonb_build_object('title', p_title, 'published', p_published));
  return v_id;
end $$;

revoke all on function public.upsert_featured(bigint, text, text, text, text, text, int, boolean, timestamptz, text) from public;
grant execute on function public.upsert_featured(bigint, text, text, text, text, text, int, boolean, timestamptz, text) to authenticated;
